def quote(value): return "'"+str(value).replace("'","''")+"'"
def main():
 sql=['-- Original N11 Part 7: 5 groups, 9 documents, 17 questions.','SET AUTOCOMMIT=0;']
 for level,(title,documents,questions,glossary) in enumerate(PACK,1):
  where=f"skill='READING' AND part_no=7 AND instructions LIKE '[READING_PART7_LEVEL:{level}]%'"
  sid=f'(SELECT id FROM practice_sets WHERE {where} ORDER BY id LIMIT 1)'
  sql.append(f"INSERT INTO practice_sets(skill,part_no,title,instructions,difficulty,is_published) SELECT 'READING',7,'Part 7 — Cấp {level}','[READING_PART7_LEVEL:{level}] Chọn đủ câu trong nhóm bài đọc để xem kết quả.','{['EASY','EASY','MEDIUM','HARD','HARD'][level-1]}',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_sets WHERE {where});")
  payload=json.dumps(dict(title=title,documents=documents,glossary=glossary),ensure_ascii=False)
  sql.append(f'INSERT INTO practice_passages(practice_set_id,passage_text,sort_order) SELECT {sid},{quote(payload)},1 WHERE NOT EXISTS(SELECT 1 FROM practice_passages WHERE practice_set_id={sid} AND sort_order=1);')
  pid=f'(SELECT id FROM practice_passages WHERE practice_set_id={sid} AND sort_order=1 ORDER BY id LIMIT 1)'
  for i,q in enumerate(questions,147):
   meta=json.dumps({k:v for k,v in q.items() if k not in ['text','options','correct']},ensure_ascii=False)
   qw=f'practice_set_id={sid} AND passage_id={pid} AND sort_order={i}'
   sql.append(f'INSERT INTO practice_questions(practice_set_id,passage_id,question_text,explanation,sort_order) SELECT {sid},{pid},{quote(q["text"])},{quote(meta)},{i} WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE {qw});')
   qid=f'(SELECT id FROM practice_questions WHERE {qw} ORDER BY id LIMIT 1)'
   for label,option in zip('ABCD',q['options']):
    sql.append(f'INSERT INTO practice_options(question_id,option_label,option_text,is_correct) SELECT {qid},{quote(label)},{quote(option)},{str(label==q["correct"]).upper()} WHERE NOT EXISTS(SELECT 1 FROM practice_options WHERE question_id={qid} AND option_label={quote(label)});')
 output='\n'.join(sql+['COMMIT;','SET AUTOCOMMIT=1;',''])
 (ROOT/'database/updates/005_reading_part7.sql').write_text(output,encoding='utf-8')
 combined=ROOT/'database/n11_toeic.sql';marker='-- BEGIN N11 READING PART 7 STARTER PACK'
 expansion=ROOT/'database/updates/006_reading_expansion.sql'
 suffix='\n-- BEGIN N11 READING EXPANSION\n'+expansion.read_text(encoding='utf-8') if expansion.exists() else ''
 combined.write_text(combined.read_text(encoding='utf-8').split(marker)[0].rstrip()+'\n\n'+marker+'\n'+output+suffix,encoding='utf-8')
if __name__=='__main__':main()
